/**
 * 商品详情页积分展示模块
 * 支持多个 .product-points-content 元素
 * 根据后台配置的积分规则，计算并展示商品可获得的积分数量
 * 支持 JPY、EUR 等不同货币格式的处理
 */
document.addEventListener('DOMContentLoaded', () => {
  const pointsContents = document.querySelectorAll('.product-points-content')
  const blockProductPoints = document.querySelector('.block-product-points')

  // 处理不同货币格式的价格展示
  const formatPriceByCurrency = (price, currency) => {
    const priceWithoutSymbol = price.substring(1)
    switch (currency) {
      case 'JPY':
        return priceWithoutSymbol
      case 'EUR':
        return priceWithoutSymbol.split(',')[0]
      default:
        return priceWithoutSymbol.split('.')[0]
    }
  }

  const init = (price) => {
    pointsContents.forEach(pointsContent => {
      const template = pointsContent.dataset.text
      let pointsRatio = pointsContent.dataset.scale

      const renderTemplate = (template, formatPrice) => {
        const customerID = pointsContent.dataset.id
        const spu = pointsContent.dataset.spu
        const btnText = pointsContent.dataset.btn
        const btnColor = pointsContent.dataset.color
        const btnBold = pointsContent.dataset.bold === 'true'
        const popType = pointsContent.dataset.pop
        const klavID = pointsContent.dataset.klav

        const btnContent = `<span class="product-points-btn"
            style="color:${btnColor}; font-weight:${btnBold ? '700' : '400'};"
          >${btnText}</span>`

        // 未登录情况：有按钮
        if (btnText && !customerID) {
          pointsContent.innerHTML = template
            .replace(/\$btn/g, btnContent)
            .replace(/\$points/g, formatPrice)

          const btn = pointsContent.querySelector('.product-points-btn')

          if (btn) {
            btn.addEventListener('click', e => {
              e.preventDefault()
              e.stopPropagation();
              if (popType === 'passwordfree_pop') {
                window?.jackeryLoginApp?.modalLogin({
                  register_act: 'SXYMB-Register',
                  return_url: window.location.href
                })
              } else if (popType === 'newuser_pop') {
                window.customerPlugin?.iconClick?.()
              } else {
                // klav 弹窗
                window._klOnsite = window._klOnsite || [];
                window._klOnsite.push(['openForm', klavID]);
              }

              // 事件埋点
              window.dataLayer = window.dataLayer || []
              window.dataLayer.push({ event_parameters: null })
              window.dataLayer.push({
                event: 'ga4Event',
                event_name: 'products_details_page_user_clicks',
                event_parameters: {
                  current_page: window.location.href,
                  product_spu_name: spu,
                  module: 'PointLogin',
                  position: 'PasswordFreeLogin',
                  button_name: btnText
                }
              })
            })
          }
        } 
        if (customerID) {
          // 已登录情况：无按钮
          if (popType === 'passwordfree_pop') {
            pointsContent.innerHTML = template
            .replace(/\$btn/g, '')
            .replace(/\$points/g, formatPrice)
          }else{
            pointsContent.innerHTML = template
            .replace(/\$btn/g, btnContent)
            .replace(/\$points/g, formatPrice)

          const btn = pointsContent.querySelector('.product-points-btn')

          if (btn) {
            btn.addEventListener('click', e => {
              e.preventDefault()
              e.stopPropagation();
              if (popType === 'newuser_pop') {
                window.customerPlugin?.iconClick?.()
              } else {
                // klav 弹窗
                window._klOnsite = window._klOnsite || [];
                window._klOnsite.push(['openForm', klavID]);
              }

              // 事件埋点
              window.dataLayer = window.dataLayer || []
              window.dataLayer.push({ event_parameters: null })
              window.dataLayer.push({
                event: 'ga4Event',
                event_name: 'products_details_page_user_clicks',
                event_parameters: {
                  current_page: window.location.href,
                  product_spu_name: spu,
                  module: 'PointLogin',
                  position: 'PasswordFreeLogin',
                  button_name: btnText
                }
              })
            })
          }
          }
        }
      }

      if (template.includes('$points')) {
        // 计算积分金额
        const basePrice = Number(price || pointsContent.dataset.price)
        pointsRatio = parseFloat(pointsRatio)
        const calculatedPoints = Math.floor((basePrice / 100) * pointsRatio) * 100

        // 格式化积分展示
        const tempPrice = window.formatMoney(
          calculatedPoints,
          window?.pageInfo?.currency?.money_format
        )
        const currency = window?.pageInfo?.currency?.currency
        const formatPrice = formatPriceByCurrency(tempPrice, currency)

        // 替换文案中的积分占位符
        pointsContent.innerHTML = template.replace(/\$points/g, formatPrice)
        renderTemplate(template, formatPrice)
      } else {
        // 不包含 $points 的情况
        pointsContent.innerHTML = template
        renderTemplate(template, '')
      }
    })
  }
  init()

  // 监听变体切换
  if (document.querySelector('variant-fields')) {
    document.addEventListener('variantChangeEvent', e => {
      const currentVariant = e.detail.variant
      if (currentVariant) {
        init(currentVariant.shopify_price || currentVariant.price)
      }
    })
  }

  // 旧（3.0） main-product 触发variant变化 - 改变当前变体
  if(document.querySelector(".variant-input-wrap")) { // 就main-product
    document.querySelector(".variant-input-wrap").querySelectorAll('label').forEach(item => {
      item.onclick = (e) => {
        const price = e.currentTarget.dataset.price
        init(price)
        console.log('price', price)
      }
    })
  }
})
